import { connect, useSelector } from 'react-redux';
import {
    SafeAreaView,
    View,
    Switch,
    Text,
    TextInput,
    ScrollView,
    TouchableOpacity
} from 'react-native';

import Select from '../../components/Select';
import TimePicker from '../../components/TimePicker';
import { SubHeader } from '../../components/Headers';
import { getLocalTime, getLocalDate } from '../../components/TimeUtils';
import { MEALTYPES } from '../../data/dummy-data';
import { buttons, colors, formStyles, generic } from '../../constants/Styles';
import { updateDate } from '../../store/modules/date';
import { selectAllCopings, createCoping } from '../../store/modules/coping';
import { selectAllFeelings, createFeeling } from '../../store/modules/feeling';
import { selectMeal, updateMeal, createMeal, deleteMeal } from '../../store/modules/meal';

export default connect(selectMeal)(Food = ({ navigation, dispatch, meal }) => {
    const currentDate = useSelector(state => state.date.currentDate);
    const allStateFeelings = useSelector(selectAllFeelings);;
    const allFeelingValues = Object.values(allStateFeelings);
    const allStateCopings = useSelector(selectAllCopings);;
    const allCopingValues = Object.values(allStateCopings);

    useEffect(() => {
        if (allCopingValues.length === 0) {
            const copings = ['Meditatie', 'Bewegen', 'Afleiding', 'Positive gedachten'];
            for(const value of copings) {
              dispatch(createCoping({title: value}));
            }
        }
        if (allFeelingValues.length === 0) {
            const feelings = ['Bang', 'Boos', 'Somber', 'Schuldig', 'Blij', 'Neutraal', 'Verdrietig'];
            for(const value of feelings) {
              dispatch(createFeeling({title: value}));
            }
        }
        dispatch(createMeal(currentDate));
    }, []);

    if (!meal) {
        return null
    }

    const onCancel = () => {
        dispatch(deleteMeal(meal.id));
        navigation.goBack();
    }

    const onTimeSelect = selected => {
        dispatch(updateMeal({dateTime: selected}));
        dispatch(updateDate(selected));
    };

    return (
        <SafeAreaView style={{ flex: 1 }}>
            <TimePicker
                timeSelect={onTimeSelect}
                mealTime={currentDate}
                text={getLocalTime(currentDate)}
            />
            <ScrollView style={formStyles.shadowProp}>
                <View style={formStyles.formContainer}>
                    <SubHeader text='Welke maaltijd wil je beschrijven?' />
                    <Select
                        singleSelect={selected => dispatch(updateMeal({type: selected}))}
                        data={MEALTYPES}
                    />
                    <SubHeader text='Wat heb je gegeten?' />
                    <View style={{marginBottom: generic.marginBottom}}>
                        <TextInput 
                            style={formStyles.textInputBox}
                            multiline={true}
                            // numberOfLines={2}
                            onChangeText={(input) => dispatch(updateMeal({content: input}))}
                            value={meal.content}
                            placeholder='Eten'
                        />
                    </View>
                    <SubHeader text='Wat heb je gedronken?' />
                    <View style={{marginBottom: generic.marginBottom}}>
                        <TextInput 
                            style={formStyles.textInputBox}
                            multiline={true}
                            // numberOfLines={2}
                            onChangeText={(input) => dispatch(updateMeal({drinks: input}))}
                            value={meal.drinks}
                            placeholder='Drinken'
                        />
                    </View>
                    <SubHeader text='Heb je de maaltijd overgeslagen?' />
                    <View style={formStyles.switchContainer}>
                        <Switch
                            trackColor={{ false: colors.lightBlue, true: colors.lightBlue }}
                            thumbColor={meal.skipped ? colors.lightGray : colors.lightGray}
                            ios_backgroundColor={colors.lightBlue}
                            onValueChange={(input) => dispatch(updateMeal({skipped: input}))}
                            value={meal.skipped}
                        />
                        <View>{
                            meal.skipped ?
                            <Text style={formStyles.switchText}>Ja</Text> :
                            <Text style={formStyles.switchText}>Nee</Text>
                        }</View>
                    </View>
                </View>
            </ScrollView>
            <View style={buttons.secondaryButtonPanel}>
                <TouchableOpacity
                    onPress={onCancel}
                    style={buttons.navButton}
                >
                    <Text style={buttons.secondaryButtonText}>{'Annuleren'}</Text>
                </TouchableOpacity>
                <TouchableOpacity
                    onPress={() => navigation.navigate('BehaviourScreen', meal)}
                    style={buttons.navButton}
                >
                    <Text style={buttons.secondaryButtonText}>{'Volgende'}</Text>
                </TouchableOpacity>
            </View>
        </SafeAreaView>
    );
});
